declare module "lunar-javascript" {
  // lunar-javascript ships no TypeScript types; we only use a handful of
  // methods, so this is intentionally loosely typed rather than a full port.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  export const Solar: any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  export const Lunar: any;
}
